"""Reuse A5 verified AVI/hold/capture packaging with A6-specific inputs."""
from prepare_a6_frames import *
src=(REPO/'godot-spike/tools/package_a5_evidence.py').read_text(encoding='utf-8-sig')
src=src.replace('prepare_a5_frames','prepare_a6_frames').replace('A5','A6').replace('a5','a6')
src=src.replace('baseline-a4','baseline-a5').replace('A4','A5').replace('a4-vs-a6','a5-vs-a6')
src=src.replace("'Passing Tests        48'","'Passing Tests        55'").replace("'Asserts            2126'","'Asserts            2772'")
src=src.replace("'rig-controls.json',OUT/'scale-measurement.json'","'geometry-check.json',OUT/'playback-check.json'")
src=src.replace("['seam-masks','protected-masks','baseline-a5']","['normalized','baseline-a5']")
src=src.replace("'tests':48,'assertions':2126","'tests':55,'assertions':2772")
src=src.replace('tests=48','tests=55')
src=src.replace("'P010':'Owner update pending; not edited'","'P010':'Owner accepted; decision record not edited'")
src=src.replace('A6 rendered reference transfer - PLACEHOLDER','A6 full-frame regeneration - PLACEHOLDER')
src=src.replace('A6 normalized reference-pixel transfer','A6 complete generated frames')
src=src.replace('A6 reference transfer','A6 complete generated frames')
src=src.replace("[OUT/'geometry-check.json',OUT/'playback-check.json',OUT/'frame-status-table.md',OUT/'sequence-check.json']", "[OUT/'geometry-check.json',OUT/'playback-check.json',OUT/'frame-status-table.md',OUT/'sequence-check.json',OUT/'METHOD.md',OUT/'W3-OBSERVATIONS.md']")
src=src.replace("sources += [p for folder in ['normalized','baseline-a5'] for p in (OUT/folder).iterdir() if p.is_file()]", "sources += [p for folder in ['normalized','baseline-a5','candidates','sequence-runtime'] for p in (OUT/folder).rglob('*') if p.is_file()]")
# A6 retains the W3 real movie rather than burning a redundant identical run.
src=src.replace("'movie-run.log'", "'w3-playback.log'")
src=src.replace("'owner_art_approval':False", "'exact_a5_mace_pose_geometry':False,'remaining_mace_failure_frame':'04','owner_art_approval':False")
src=src.replace("avi=ROOT/'.godot/spike02-a6-movie/attack.avi';data=avi.read_bytes()", "avi=ROOT/'.godot/spike02-a6-movie/attack.avi';data=avi.read_bytes()\n    assert load(OUT/'playback-check.json')['source_movie_sha256']==sha(avi), 'W3 playback binds the same retained W5 native movie'")
src=src.replace(".splitlines())+'\\n',encoding=", ".splitlines()).rstrip()+'\\n',encoding=")
src=src.replace('regions.width,1690','regions.width,1635').replace('regions.width,2065','regions.width,2030')
src=src.replace('(10,1700)','(10,1655)').replace('(i*340,1725)','(i*340,1680)').replace('i*340+4,2048','i*340+4,2008')
(REPO/'godot-spike/tools/package_a6_evidence.py').write_text(src,encoding='utf-8',newline='\n')
print('A6_PACKAGE source generated; native W3 movie is W5 clip authority')
